insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('5cdb7c53-e0d6-5d67-b5cc-445da9d6e7d3', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'What is the cost, in dollars, for the manufacturer to make $50$ rings?', '["$100$", "$125$", "$175$", "$225$"]'::jsonb, 1, 'The cost $y$, in dollars, for a manufacturer to make $x$ rings is represented by the line shown.

![figure](/q/mar25/002.webp)'),
  ('3f524c6e-4275-5305-af0a-4fa2e304c48b', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'Which expression is equivalent to $9(x^{2} + 6)$?', '["$9x^{2} + 3$", "$9x^{2} + 6$", "$9x^{2} + 15$", "$9x^{2} + 54$"]'::jsonb, 2, null),
  ('0c21e228-3021-5b69-a1f4-a0c2c8c26f1f', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'The solution to a system of linear equations is $(5,5)$. Which of the following could be the graph of the equations in the system?', '["![figure](/q/mar25/003.webp)", "![figure](/q/mar25/004.webp)", "![figure](/q/mar25/005.webp)", "![figure](/q/mar25/006.webp)"]'::jsonb, 3, null),
  ('98cbe99a-25fd-52cf-89f8-b1883a9d62b0', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'In the given equation, k is a constant. The equation has infinitely many solutions. What is the value of k?
$7x + 21 = 7x + k$', '[]'::jsonb, 4, null),
  ('e95af95d-2bfd-5d58-a47f-f390f8511b55', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'The function $f$ is defined by $f(x) = 2x - \frac{1}{4}$. What is the $y$-intercept of the graph of $y = f(x)$ in the $xy$- plane?', '["$(0,-\\frac{1}{4})$", "$(0,-2)$", "$(0,2)$", "$(0,4)$"]'::jsonb, 5, null),
  ('8233f233-28ba-5936-a0f5-0e81eb2a47aa', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'The list gives the mass, in grams, of $5$ ruffed lemurs. $(3810;3810;3530;3850;3550)$ What is the mean mass, in grams, of these $5$ ruffed lemurs?', '[]'::jsonb, 6, null),
  ('32da73e5-4eab-5770-948b-6587f3d1935c', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'The price of an object increased from \$16 to \$80. What was the percent increase in the price of the object?', '["20%", "64%", "80%", "400%"]'::jsonb, 7, null),
  ('730e2d45-f341-5c1f-b3c0-e2372e4a02ee', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'In the figure shown, triangle $CAE$ is similar to triangle $CBD$. The measure of angle $CBD$ is $59°$, and $AE = 2 \cdot (BD)$. What is the measure of angle $CAE$?', '["$(28 ∗ 59)°$", "$(28 + 59)°$", "$59°$", "$28°$"]'::jsonb, 8, '![figure](/q/mar25/007.webp)'),
  ('e1c9b9b8-1aa2-5c1d-874c-e530d9fecc21', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'A student needs at least $190$ signatures from classmates to run for class president. The student collects $30$ signatures on Monday and collects enough additional signatures on Tuesday to run for class president. Which inequality represents the number of additional signatures, $s$, that the student collects on Tuesday?', '["$s + 30 \\le 190$", "$s + 30 \\ge 190$", "$s - 30 \\le 190$", "$s - 30 \\ge 190$"]'::jsonb, 9, null),
  ('1da6f396-d8c2-5e7b-b65d-3e2146c8dfb8', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'Which expression is equivalent to $7x^{6} - 14x^{2}$, where $x > 0$?', '["$7(x^{3} - 2x^{2})^{2}$", "$x^{2}(7x - 2)^{4}$", "$7x^{2}(x - 2)^{4}$", "$7x^{2}(x^{4} - 2)$"]'::jsonb, 10, null),
  ('48f4a988-b469-5a7f-a768-9d7f5485b506', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'The graph of a polynomial function $y = f(x)$ in the $xy$-plane passes through the point $(5,7)$. What is the value of $f(5)$?', '["$7$", "$5$", "$12$", "$35$"]'::jsonb, 11, null),
  ('6f217a25-4f4a-542f-b0ca-7be6b5d0ba53', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', '$8x^{2} + 13x = 6$
What is the positive solution to the given equation?', '[]'::jsonb, 12, null),
  ('9867cdf8-bb5f-5959-9035-a41294bbed11', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'Harper has \$110 in an account. Each year she expects to have 2.7% more money in the account than she had the previous year. Which of the following models best describes how Harper expects the money in her account to change over time?', '["Decreasing exponential", "Decreasing linear", "Increasing exponential", "Increasing linear"]'::jsonb, 13, null),
  ('c4572bd3-149d-5811-ae47-a9c3f08ffc9f', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'In right triangle $RST$, the sum of the measures of angle $R$ and angle $S$ is 90 degrees. The value of $\sin (R)$ is $\frac{2\sqrt{10}}{7}$. What is the value of $\cos (S)$?', '["$\\frac{3\\sqrt{10}}{20}$", "$\\frac{2\\sqrt{10}}{7}$", "$\\frac{7\\sqrt{10}}{20}$", "$\\frac{2\\sqrt{10}}{3}$"]'::jsonb, 14, null),
  ('b6c27f92-0499-5234-8ad6-92497ab42d75', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'Line $t$ is defined by $y = -\frac{1}{2}x + 14$. Line $s$ is perpendicular to line $t$ in the $xy$-plane. What is the slope of line $s$?', '["14", "2", "$\\frac{1}{2}$", "$\\frac{1}{14}$"]'::jsonb, 15, null),
  ('f14fb680-ecbb-5ddf-bba8-199e958c015d', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', '$f(x) = 8(2)^{\frac{x}{4}}$
Which table gives four values of $x$ and their corresponding values of $f(x)$ for the given exponential function?', '["| x | -4 | 0 | 4 | 8 |\n| f(x) | 4 | 0 | 10 | 40 |", "| x | -4 | 0 | 4 | 8 |\n| f(x) | 4 | 8 | 16 | 32 |", "| x | -4 | 0 | 4 | 8 |\n| f(x) | -4 | 8 | 18 | 36 |", "| x | -4 | 0 | 4 | 8 |\n| f(x) | 4 | 8 | 12 | 24 |"]'::jsonb, 16, null),
  ('7bd97f07-55a1-560d-891f-63c0a222c09e', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'The measure of angle $C$ is $\frac{3π}{4}$ radians. What is the value of $\cos (C)$?', '["$-\\frac{\\sqrt{2}}{2}$", "$-\\frac{1}{2}$", "$\\frac{\\sqrt{2}}{2}$", "$\\frac{\\sqrt{3}}{2}$"]'::jsonb, 17, null),
  ('e3667782-3b66-57a3-8de9-74a2395515e3', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', '$7y = -6x + 2,170$
$24x - 28y = 1,400$
The solution to the given system of equations is $(x,y)$. What is the value of $x + y$?', '[]'::jsonb, 18, null),
  ('ae179631-0d87-53ac-8347-3c14d0578815', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'A researcher observes a sample of a nuclide. An exponential model estimates that the mass, in grams, of the sample decreases by 23% every $11.69$ minutes. Which of the following equations could represent this model, where $M$ is the estimated mass, in grams, of the sample $t$ minutes after the researcher began observing the sample?', '["$M = 100(0.77)^{\\frac{t}{11.69}}$", "$M = 100(0.77)^{t+11.69}$", "$M = 100(0.23)^{\\frac{t}{11.69}}$", "$M = 100(0.23)^{t+11.69}$"]'::jsonb, 19, null),
  ('427c42af-c7c9-583b-a420-11e266d3a6ed', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', '$-4∣5x + 4∣ + 2 = -14$
What are all solutions to the given equation?', '["0", "0 and $-\\frac{1}{5}$", "0 and $-\\frac{8}{5}$", "There is no solution."]'::jsonb, 20, null),
  ('9a3bfd9e-aedd-5285-8b3c-f76825c3bd42', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'For the right circular cone shown, $B$ is a point on the circumference of the base, and the length of segment $AB$ (not shown) is $84$ centimeters. If the height of the cone is $42$ centimeters and the volume of the cone is $kπ$ cubic centimeters, what is the value of $k$?', '[]'::jsonb, 21, '![figure](/q/mar25/008.webp)'),
  ('911313f3-7141-539e-933a-2a94284c2809', 'dcc48e8a-b41c-532e-aab0-1312118a5d9b', 'A sphere has a volume of $247$ cubic yards. What is the volume of the sphere, in cubic <u>meters</u>? (Use $1$ yard = $0.914$ meter.)', '[]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('5cdb7c53-e0d6-5d67-b5cc-445da9d6e7d3', 2, null, '**Choice C is correct.** To find the cost for the manufacturer to make 50 rings, locate the point on the graph where $x = 50$. At this point, the corresponding $y$-value, which represents the cost in dollars, is 175. Therefore, the cost to make 50 rings is \$175.
Here’s a breakdown of why the other options are incorrect:
**Option A (\$100):** This cost corresponds to making approximately 0 rings, not 50.
**Option B (\$125):** This cost appears around 20 rings, not 50.
**Option D (\$225):** This cost is reached closer to 70 rings, not 50.'),
  ('3f524c6e-4275-5305-af0a-4fa2e304c48b', 3, null, '**Choice D is correct.** Distribute 9 across the sum: $9(x^{2} + 6) = 9 \cdot x^{2} + 9 \cdot 6 = 9x^{2} + 54$, which matches choice D.
**Choice A is incorrect.** Multiplying gives $9x^{2} + 54$, not $9x^{2} + 3$; 3 is not equal to $9 \cdot 6$.
**Choice B is incorrect.** The constant term should be $9 \cdot 6 = 54$, not 6; $9(x^{2} + 6) \ne 9x^{2} + 6$.
**Choice C is incorrect.** The constant 15 does not come from $9 \cdot 6$; the correct constant is 54, so $9x^{2} + 15$ is wrong.
**Faster approach:** Use the distributive property immediately: multiply the outside number by each term inside the parentheses ($9 \cdot x^{2}$ and $9 \cdot 6$) to get the equivalent expression.'),
  ('0c21e228-3021-5b69-a1f4-a0c2c8c26f1f', 3, null, '**Choice D is correct.** Both lines in choice D cross at the grid point with coordinates (5, 5): if you follow the x-axis to 5 and go up to y = 5, you land exactly where the two lines meet. That single intersection at (5,5) matches the system’s solution.
**Choice A is incorrect.** The two lines in A intersect at the origin (0,0), not at (5,5); following the grid shows their crossing point is at x = 0, y = 0.
**Choice B is incorrect.** The lines in B intersect at a point near (4,4) (one tick left of the (5,5) square), so their intersection is not (5,5).
**Choice C is incorrect.** The two lines in C are parallel (same slope) and do not intersect at any point, so they cannot have the single solution (5,5).
**Faster approach:** On any graph-question asking for a specific solution (a, b), first locate the grid point (a, b) by counting ticks from the axes; then check whether both lines pass through that exact grid point. This immediately rules out any graph where the lines meet at a different grid point or don’t meet there at all.'),
  ('98cbe99a-25fd-52cf-89f8-b1883a9d62b0', null, array['21']::text[], '**The correct answer is 21.** Subtract $7x$ from both sides of the equation $7x + 21 = 7x + k$ to obtain $21 = k$. For the equation to have infinitely many solutions, the variable terms must cancel and the remaining constants must be equal; since $7x$ cancels on both sides, the constants must match, so $k = 21$.
**Faster approach:** Immediately subtract $7x$ from both sides to see the condition becomes $21 = k$, so set $k =$ $21$. This quick cancellation works for any linear equation where identical coefficients on both sides imply checking equality of the constant terms.'),
  ('e95af95d-2bfd-5d58-a47f-f390f8511b55', 0, null, '**Choice A is correct.** The y-intercept is the point where $x = 0$. Substituting $x = 0$ into $f(x) = 2x - \frac{1}{4}$ gives $f(0) = 2(0) - \frac{1}{4} = -\frac{1}{4}$, so the y-intercept is $(0,-\frac{1}{4})$.
**Choice B is incorrect.** Substituting $x = 0$ does not give $-2$; $f(0) = -\frac{1}{4}$, not $-2$.
**Choice C is incorrect.** The value $2$ would result from $f(0) = 2$, but $f(0) = -\frac{1}{4}$, so $(0,2)$ is wrong. **Choice D is incorrect.** The value $4$ is not produced by $f(0)$; $f(0) = -\frac{1}{4}$, so $(0,4)$ is incorrect.
**Faster approach:** For any linear function $ax + b$, the y-intercept is simply $(0,b)$. Here $b = -\frac{1}{4}$, so the intercept is $(0,-\frac{1}{4})$.'),
  ('8233f233-28ba-5936-a0f5-0e81eb2a47aa', null, array['3710']::text[], '**The correct answer is 3710.** To find the mean, add the five masses and divide by 5. The sum is $3810 + 3810 +$ $3530 + 3850 + 3550 = 18550$. Dividing by 5 gives $18550 \div 5 = 3710$, so the mean mass is $3710$ grams.
**Faster approach:** Pair numbers to simplify addition: $(3810 + 3550) = 7360$ and $(3810 + 3530) = 7340$, then add the remaining $3850$ to get $7360 + 7340 + 3850 = 18550$, then divide by 5 to get $3710$. This reduces the chance of arithmetic errors when computing the sum.'),
  ('32da73e5-4eab-5770-948b-6587f3d1935c', 3, null, '**Choice D is correct.** The percent increase is found by dividing the change by the original amount: the change is $80 - 16 = 64$, and the original price is $16$, so the percent increase is $\frac{64}{16} = 4$, which is $400%$.
**Choice A is incorrect.** A 20% increase of $16$ would be $0.20 \times 16 = 3.2$, giving a new price of $19.2$, not $80$.
**Choice B is incorrect.** A 64% increase of $16$ would be $0.64 \times 16 = 10.24$, giving a new price of $26.24$, not $80$.
**Choice C is incorrect.** An 80% increase of $16$ would be $0.80 \times 16 = 12.8$, giving a new price of $28.8$, not $80$.
**Faster approach:** Compute percent increase as $(\text{new} - \text{original})/\text{original}$; here $(80 - 16)/16 = 64/16 =$ $4 = 400%$, a single quick division.'),
  ('730e2d45-f341-5c1f-b3c0-e2372e4a02ee', 2, null, '**Choice C is correct.** If triangle CAE is similar to triangle CBD (in that order), then corresponding vertices pair: C↔C, A↔B, and E↔D. Therefore the angle at A in triangle CAE corresponds to the angle at B in triangle CBD, so ∠CAE = ∠CBD = 59°.
**Choice A is incorrect.** The product (28·59)° is not supported by similarity: similarity gives equality of corresponding angles, not multiplication.
**Choice B is incorrect.** The sum (28+59)° is not implied by the given information; corresponding angles are equal, not additive.
**Choice D is incorrect.** The value 28° is not justified; the given side-length relation AE = 2·BD only fixes the scale factor, not a different angle.
**Faster approach:** From the similarity statement read off corresponding vertices in order; corresponding angles are equal, so ∠CAE equals ∠CBD immediately.'),
  ('e1c9b9b8-1aa2-5c1d-874c-e530d9fecc21', 1, null, '**Choice B is correct.** The student has 30 signatures already and collects $s$ more on Tuesday, so the total number of signatures is $30 + s$. The requirement is at least 190 signatures, which is represented by the inequality $30 + s \ge 190$, or $s + 30 \ge 190$, which is choice B.
**Choice A is incorrect.** $s + 30 \le 190$ would mean the student has at most 190 signatures, but the problem requires at least 190, so the inequality sign is reversed.
**Choice C is incorrect.** $s - 30 \le 190$ does not represent the total signatures; it subtracts 30 from $s$ instead of adding the 30 already obtained, so it models the wrong quantity.
**Choice D is incorrect.** $s - 30 \ge 190$ also uses $s - 30$ instead of $s + 30$, so it does not represent the actual total and is therefore incorrect.
**Faster approach:** Write the total as "30 plus s" and translate "at least 190" to $\ge 190$, giving $30 + s \ge 190$ immediately.'),
  ('1da6f396-d8c2-5e7b-b65d-3e2146c8dfb8', 3, null, '**Choice D is correct.** Factor the greatest common factor $7x^{2}$ from $7x^{6} - 14x^{2}$: $7x^{6} - 14x^{2} = 7x^{2}(x^{4} - 2)$, which matches choice D.
**Choice A is incorrect.** Squaring $x^{3} - 2x^{2}$ gives $x^{6} - 4x^{5} + 4x^{4}$, and multiplying by 7 produces extra terms ( $-4x^{5}$, $+4x^{4}$) not present in the original expression.
**Choice B is incorrect.** Expanding $(7x - 2)^{4}$ yields terms with powers of $x$ higher than 4 and coefficients that do not match; multiplying by $x^{2}$ does not produce $7x^{6} - 14x^{2}$.
**Choice C is incorrect.** $(x - 2)^{4}$ expands to $x^{4} - 8x^{3} + 24x^{2} - 32x + 16$, so $7x^{2}(x - 2)^{4}$ contains many extra terms and coefficients that differ from the original expression.
**Faster approach:** Always look for and factor out the greatest common factor first; here $7x^{2}$ is common to both terms, immediately yielding the equivalent expression $7x^{2}(x^{4} - 2)$.'),
  ('48f4a988-b469-5a7f-a768-9d7f5485b506', 0, null, '**Choice A is correct.** If the graph of $y = f(x)$ passes through the point $(5,7)$, then by definition the function value at $x = 5$ is $f(5) = 7$ — the $y$-coordinate of that point.
**Choice B is incorrect.** The $x$-coordinate of the point is $5$, not the function value; $f(5)$ equals the $y$- coordinate, which is $7$, not $5$.
**Choice C is incorrect.** There is no information in the point $(5,7)$ that yields $12$; that number does not match either coordinate.
**Choice D is incorrect.** The product $5 \times 7 = 35$ is irrelevant — $f(5)$ is the $y$-coordinate $7$, not a multiplication of coordinates.
**Faster approach:** Remember that a point $(a,b)$ on the graph of $y = f(x)$ means $f(a) = b$; immediately read off the $y$-coordinate.'),
  ('6f217a25-4f4a-542f-b0ca-7be6b5d0ba53', null, array['3/8']::text[], '**The correct answer is 3/8.** Solve $8x^{2} + 13x - 6 = 0$ with the quadratic formula: $x =$
$\frac{-13 \pm \sqrt{13^{2} - 4(8)(-6)}}{2(8)} = \frac{-13 \pm \sqrt{169 + 192}}{16} = \frac{-13 \pm \sqrt{361}}{16} = \frac{-13 \pm 19}{16}$. The positive solution is $x =$ $\frac{-13 + 19}{16} = \frac{6}{16} = \frac{3}{8}$.
**Faster approach:** Use the quadratic formula for any quadratic — it always works. As a faster check on this specific problem, notice the trinomial factors: $8x^{2} + 13x - 6 = (8x - 3)(x + 2)$, giving roots $x = 3/8$ and $x = -2$, so the positive root is $3/8$.'),
  ('9867cdf8-bb5f-5959-9035-a41294bbed11', 2, null, '**Choice C is correct.** The account increases by a fixed percent (2.7%) each year, which is a multiplicative change and therefore exponential growth. The amount after $t$ years is $110(1.027)^{t}$, so the model is an increasing exponential function.
**Choice A is incorrect.** A decreasing exponential would represent a fixed percent decrease each year (values getting smaller), but Harper’s amount increases by 2.7% annually, not decreases.
**Choice B is incorrect.** A decreasing linear model would mean the account loses a fixed amount each year; Harper’s change is a percent (multiplicative), not a fixed subtraction, and it increases rather than decreases.
**Choice D is incorrect.** An increasing linear model would add the same dollar amount each year. Because Harper’s growth is 2.7% of the current balance (multiplicative), the correct model is exponential, not linear.
**Faster approach:** Any time a quantity changes by a fixed percent each period, immediately choose an exponential growth/decay model; percent increase >0 → increasing exponential.'),
  ('c4572bd3-149d-5811-ae47-a9c3f08ffc9f', 1, null, '**Choice B is correct.** In a right triangle, complementary acute angles satisfy $R + S = 90°$, so $\cos (S) =$ $\sin (90° - S) = \sin (R)$. The problem gives $\sin (R) = \frac{2\sqrt{10}}{7}$, so $\cos (S) = \frac{2\sqrt{10}}{7}$.
**Choice A is incorrect.** $\frac{3\sqrt{10}}{20} \approx 0.474$ which does not equal $\sin (R)$ and is not produced by the complementary-angle identity.
**Choice C is incorrect.** $\frac{7\sqrt{10}}{20} \approx 1.106$ exceeds 1, so it cannot be a cosine value for an acute angle in a triangle. **Choice D is incorrect.** $\frac{2\sqrt{10}}{3} \approx 2.108$ is also greater than 1 and therefore impossible for a cosine of an acute angle.
**Faster approach:** Use the complementary-angle identity $\cos (S) = \sin (90° - S) = \sin (R)$ immediately; pick the given sine value.'),
  ('b6c27f92-0499-5234-8ad6-92497ab42d75', 1, null, '**Choice B is correct.** Line t has slope $-frac12$. A line perpendicular to another in the plane has slope equal to the negative reciprocal of the original slope. The negative reciprocal of $-frac12$ is $2$, so the slope of line s is $2$.
**Choice A is incorrect.** The value $14$ is the y-intercept of line t (from $y = -\frac{1}{2}x + 14$), not a slope; it does not satisfy the negative-reciprocal relation for perpendicular slopes.
**Choice C is incorrect.** $\frac{1}{2}$ is the reciprocal of $2$, not the negative reciprocal of $-\frac{1}{2}$; it does not reverse the sign as required for perpendicular lines.
**Choice D is incorrect.** $\frac{1}{14}$ is unrelated to the slope $-\frac{1}{2}$ (it would be the reciprocal of 14), and does not satisfy the negative-reciprocal rule.
**Faster approach:** For any line with slope $m$, a perpendicular line has slope $-1/m$. Apply that rule directly: $-1/(-\frac{1}{2}) = 2$.'),
  ('f14fb680-ecbb-5ddf-bba8-199e958c015d', 1, null, '**Choice B is correct.** For $f(x) = 8(2)^{x/4}$ evaluate at each listed $x$. When $x = -4$, $f(-4) = 8(2)^{-1} = 8 \cdot \frac{1}{2} = 4$. When $x = 0$, $f(0) = 8(2)^{0} = 8$. When $x = 4$, $f(4) = 8(2)^{1} = 16$. When $x = 8$, $f(8) = 8(2)^{2} = 32$. The row (4, 8, 16, 32) matches choice B exactly.
**Choice A is incorrect.** It lists $f(0) = 0$ and $f(4) = 10$, both of which contradict direct evaluation ($f(0) = 8$, $f(4) = 16$).
**Choice C is incorrect.** It gives $f(-4) = -4$ and $f(4) = 18$, but $f(-4) = 4$ and $f(4) = 16$, so the values are wrong.
**Choice D is incorrect.** It shows $f(4) = 12$ and $f(8) = 24$, but actual values are $16$ and $32$, so this table is not consistent with the function.
**Faster approach:** Note that increasing $x$ by $4$ multiplies $f(x)$ by $2$ (because of the $2^{x/4}$). Start at $x = 0$ where $f(0) = 8$, then multiply or divide by $2$ for steps of $4$ to get the other entries quickly.'),
  ('7bd97f07-55a1-560d-891f-63c0a222c09e', 0, null, '**Choice A is correct.** The angle $C = \frac{3π}{4}$ equals $135°$, which lies in the second quadrant where cosine is negative. The reference angle is $π/4$ (or $45°$), and $\cos (π/4) = \frac{\sqrt{2}}{2}$, so $\cos (\frac{3π}{4}) = -\frac{\sqrt{2}}{2}$.
**Choice B is incorrect.** $-\frac{1}{2}$ is the cosine of $120°$ (or $\frac{2π}{3}$), not $135°$.
**Choice C is incorrect.** $\frac{\sqrt{2}}{2}$ is the cosine of $45°$ (or $π/4$), but $\cos (\frac{3π}{4})$ is negative because the angle is in quadrant II.
**Choice D is incorrect.** $\frac{\sqrt{3}}{2}$ is the cosine of $30°$ (or $π/6$) and is positive; it does not match the value at $\frac{3π}{4}$. **Faster approach:** Memorize unit-circle values for common angles and quadrant signs; for $\frac{3π}{4}$ locate the mirror of $π/4$ in quadrant II, giving $-\frac{\sqrt{2}}{2}$.'),
  ('e3667782-3b66-57a3-8de9-74a2395515e3', null, array['340']::text[], '**The correct answer is 340.** Rewrite the first equation in standard form: $7y = -6x + 2170$ gives $6x + 7y =$ $2170$. Multiply that equation by 4 to get $24x + 28y = 8680$. Now add this to the second equation, $24x -$ $28y = 1400$, to eliminate $y$: $48x = 10080$, so $x = 210$. Substitute into $y = (-6/7)x + 310$ (from the original first equation): $y = (-6/7)(210) + 310 = -180 + 310 = 130$. Thus $x + y = 210 + 130 = 340$.
**Faster approach:** Put the first equation into $6x + 7y = 2170$, multiply it by 4 to produce $24x + 28y = 8680$, then add to $24x - 28y = 1400$ to eliminate $y$ immediately and solve for $x$; substitute to get $y$ and then $x + y$. This elimination by scaling is the quickest general method for solving two linear equations.'),
  ('ae179631-0d87-53ac-8347-3c14d0578815', 0, null, '**Choice A is correct.** A 23% decrease each 11.69 minutes means the remaining fraction after each 11.69- minute period is $1 - 0.23 = 0.77$. If $M(0) = 100$, then after $t$ minutes there are $t/11.69$ such periods, so $M =$ $100(0.77)^{t/11.69}$.
**Choice B is incorrect.** Using $t + 11.69$ in the exponent does not model repeated multiplicative periods; the exponent should be proportional to the number of 11.69-minute periods, not shifted by 11.69.
**Choice C is incorrect.** The base $0.23$ represents the fraction lost each period, not the fraction remaining. Using $0.23^{t/11.69}$ would make the mass far too small (and would be 0 at $t = 0$ only if multiplied differently).
**Choice D is incorrect.** Like B, it incorrectly uses $t + 11.69$ in the exponent, and like C it uses the loss fraction instead of the remaining fraction.
**Faster approach:** Recognize “decreases by 23% every 11.69 minutes” means multiply by $0.77$ each 11.69 minutes, so use $M = M_{0}(0.77)^{t/11.69}$.'),
  ('427c42af-c7c9-583b-a420-11e266d3a6ed', 2, null, '**Choice C is correct.** Start by isolating the absolute value: $-4∣5x + 4∣ + 2 = -14$ gives $-4∣5x + 4∣ = -16$, so $∣5x + 4∣ = 4$. Solve the two resulting linear equations: $5x + 4 = 4$ yields $x = 0$, and $5x + 4 = -4$ yields $5x =$ $-8$, so $x = -\frac{8}{5}$. Thus the solutions are $0$ and $-\frac{8}{5}$.
**Choice A is incorrect.** It lists only $0$, but the second case of the absolute-value equation produces $x = -\frac{8}{5}$ as well.
**Choice B is incorrect.** It lists $0$ and $-\frac{1}{5}$; $-\frac{1}{5}$ does not satisfy $5x + 4 = \pm 4$ (it gives $5x + 4 = 3$), so it is not a solution.
**Choice D is incorrect.** There are real solutions, shown above, so the statement that there is no solution is false.
**Faster approach:** Isolate the absolute value, then split into the two linear cases $5x + 4 = 4$ and $5x + 4 = -4$ and solve—this method always works for equations of the form $∣A∣ = B$ with $B \ge 0$.'),
  ('9a3bfd9e-aedd-5285-8b3c-f76825c3bd42', null, array['74088']::text[], '**The correct answer is 74088.** The segment AB is the slant height $l$ of the right circular cone, so $l = 84$. For a right cone, $l^{2} = r^{2} + h^{2}$, so $r^{2} = l^{2} - h^{2} = 84^{2} - 42^{2} = (84 - 42)(84 + 42) = 42 \cdot 126 = 5292$. The volume is $V = \frac{1}{3}π r^{2}h$, so $k = \frac{1}{3}r^{2}h = \frac{1}{3} \cdot 5292 \cdot 42 = 5292 \cdot 14 = 74088.$
**Faster approach:** Use $r^{2} = l^{2} - h^{2}$ (Pythagorean relation for slant height) and substitute directly into $k =$ $\frac{1}{3}r^{2}h$, so compute $k = \frac{1}{3}(l^{2} - h^{2})h$ to avoid separately finding $r$.'),
  ('911313f3-7141-539e-933a-2a94284c2809', null, array['943/5']::text[], '**The correct answer is 943/5 (≈188.6).** Convert yards to meters by cubing the linear factor: $1 \text{yd} =$ $0.914 \text{m} = \frac{457}{500} \text{m}$, so $1 \text{yd}^{3} = (\frac{457}{500})^{3}\text{m}^{3}$. The sphere’s volume in cubic meters is $247 \cdot (\frac{457}{500})^{3}$. Writing this exactly gives $247 \cdot \frac{457^{3}}{500^{3}} = \frac{23574666271}{125000000} \approx 188.597330168 \text{m}^{3}$, which rounds to $188.6 = \frac{943}{5} \text{m}^{3}$. **Faster approach:** Convert the linear unit as an exact fraction ($0.914 = 457/500$), cube that fraction once, and multiply by the given volume. Working with the fractional form avoids repeated decimal multiplication and yields an exact value you can round if required.')
