insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('e89632f1-a5e9-53bd-8fb1-5b94769d660d', '413f6697-3442-5053-b12e-926fa81b6a8c', '$y = 3x + 13$
$y = 3x^{2} + 13$
Which ordered pair $(x,y)$ is a solution to the given system of equations?', '["$(0,0)$", "$(0,13)$", "$(26,91)$", "$(26,169)$"]'::jsonb, 1, null),
  ('aaeacdd0-8dac-59d0-93a2-7606fc794613', '413f6697-3442-5053-b12e-926fa81b6a8c', 'A certain elephant calf weighed $226$ pounds when it was born. The elephant calf gained an average of $3$ pounds per day in its first year of life. Which equation models this situation, where $y$ is the estimated weight of the elephant calf, in pounds, $x$ days after it was born?', '["$y = 226 + 3x$", "$y = 226 - 3x$", "$y = 3 + 226x$", "$y = 3 - 226x$"]'::jsonb, 2, null),
  ('ef0833a8-092f-5bc5-b028-3a76e4e633e6', '413f6697-3442-5053-b12e-926fa81b6a8c', 'Audrey’s hair will grow at a constant rate from a length of $7$ inches to a length of $11$ inches. The equation $0.6t + 7 = 11$ describes this situation, where $t$ is the number of months it will take for Audrey’s hair to reach a length of $11$ inches. Which of the following is the best interpretation of $0.6$ in this context?', '["The time, in months, it will take Audrey’s hair to grow 1 inch", "The length, in inches, Audrey’s hair will grow each month", "The time, in months, it will take Audrey’s hair to reach a length of 11 inches", "The length, in inches, Audrey’s hair will grow in 11 months"]'::jsonb, 3, null),
  ('544db19e-191d-5575-8116-fcb40fd03ee2', '413f6697-3442-5053-b12e-926fa81b6a8c', 'A rectangle has a length that is $31$ times its width. The function $y = (31w)(w)$ represents this situation, where $y$ is the area, in square feet, of the rectangle and $y > 0$. Which of the following is the best interpretation of $31w$ in this context?', '["The length of the rectangle, in feet", "The area of the rectangle, in square feet", "The difference between the length and the width of the rectangle, in feet", "The width of the rectangle, in feet"]'::jsonb, 4, null),
  ('8dadda52-cfd8-5132-865f-93215627dc40', '413f6697-3442-5053-b12e-926fa81b6a8c', 'Which of the following expressions is equivalent to $11x^{10} - 11x^{9} + 77x$ ?', '["$x(10x^{10} - 10x^{9} + 76x)$", "$x(11x^{10} - 11x^{9} + 77)$", "$11x(x^{10} - x^{9} + 7x)$", "$11x(x^{9} - x^{8} + 7)$"]'::jsonb, 5, null),
  ('74c4b860-0795-5212-b200-6fe03da51b0b', '413f6697-3442-5053-b12e-926fa81b6a8c', 'For $x > 0$, the function $f$ is defined as follows: $f(x)$ equals $293%$ of $x$ Which of the following could describe this function?', '["Decreasing exponential", "Decreasing linear", "Increasing exponential", "Increasing linear"]'::jsonb, 6, null),
  ('63c511be-4a6a-5fec-9f89-5d21a883fe28', '413f6697-3442-5053-b12e-926fa81b6a8c', 'At a convention center, there are a total of $225$ visitors. Each visitor is located in either room $A$, room $B$, or room $C$. If one of these visitors is selected at random, the probability of selecting a visitor who is located in room $A$ is $0.72$, and the probability of selecting a visitor who is located in room $B$ is $0.24$. How many visitors are located in room $C$?', '["$4$", "$9$", "$39$", "$108$"]'::jsonb, 7, null),
  ('8605a4aa-75a2-52d9-b4c4-c01d6dba5a61', '413f6697-3442-5053-b12e-926fa81b6a8c', '$f(x) = 5(g(x)) - 3$
$g(x) = ∣12x - 7∣$
The functions $f$ and $g$ are defined by the given equations. What is the value of $f(-10)$?', '["$-53$", "$127$", "$632$", "$643$"]'::jsonb, 8, null),
  ('47af07a4-7af0-50d8-99ce-0028acce2b3d', '413f6697-3442-5053-b12e-926fa81b6a8c', 'In right triangle $ABC$, angles $A$ and $B$ are acute, side $AC$ has a length of $28.2$, and $\tan B = \frac{1}{3}$. What is the length of side $BC$ rounded to the nearest tenth?', '["$795.2$", "$84.6$", "$9.4$", "$5.3$"]'::jsonb, 9, null),
  ('d636c702-d75d-5353-b08d-f170a410e9a9', '413f6697-3442-5053-b12e-926fa81b6a8c', 'If $16 - 5(3 - 7x) = 4 - 6(3 - 7x)$, what is the value of $3 - 7x$?', '[]'::jsonb, 10, null),
  ('27b0abfc-0476-5f26-9aa9-650a5486f554', '413f6697-3442-5053-b12e-926fa81b6a8c', 'For the linear function $p$, $p(c) = -5$, where $c$ is a constant, $p(3) = 23$ and the slope of the graph of $y = p(x)$ in the $xy$-plane is $7$. For the linear function $t$, $t(c) = -6$ and $t(4) = 34$. What is the slope of the graph of $y = t(x)$ in the $xy$-plane?', '["$-1$", "2", "7", "8"]'::jsonb, 11, null),
  ('aae44b26-6a7c-580d-a678-0ba52727c73c', '413f6697-3442-5053-b12e-926fa81b6a8c', 'The positive number $a$ is 2136% of the sum of the positive numbers $b$ and $c$, and $b$ is 89% of $c$. What percent of $b$ is $a$?', '["4,54%", "2,40%", "40.37%", "22.25%"]'::jsonb, 12, null),
  ('9682493b-25a8-594d-931f-5d0eb70ee0dc', '413f6697-3442-5053-b12e-926fa81b6a8c', 'The function $F$ gives the temperature, in degrees Fahrenheit, that corresponds to a temperature of $x$ kelvins. If a temperature increased by $7.70$ kelvins, by how much did the temperature increase, in degrees Fahrenheit?
$F(x) = \frac{9}{5}(x - 273.15) + 32$', '[]'::jsonb, 13, null),
  ('7054ca17-348b-547a-8f16-8400e48c51a4', '413f6697-3442-5053-b12e-926fa81b6a8c', 'The function $f$ is a quadratic function. In the xy-plane, the graph of $y = f(x)$ has a vertex at $(1,4)$ and passes through the points $(2,27)$ and $(-1,96)$. What is the value of $f(-2) - f(0)$?', '["$73$", "$119$", "$184$", "$211$"]'::jsonb, 14, null),
  ('5ec4054a-2676-5563-bd76-e34e2b7da05d', '413f6697-3442-5053-b12e-926fa81b6a8c', '', '["$sx + 5y = 18s$", "$5x + sy = 18s$", "$5x + sy = 18$", "$sx + 5y = 18$"]'::jsonb, 15, 'The table shows three values of $x$ and their corresponding values of $y$, where $s$ is a constant. There is a linear relationship between $x$ and $y$. Which of the following equations represents this relationship?

| x | y |
| -2s | 28 |
| -s | 23 |
| s | 13 |'),
  ('ebc57093-cc6f-5b50-886f-3a68799bcf8c', '413f6697-3442-5053-b12e-926fa81b6a8c', 'The triangle inequality theorem states that the sum of any two sides of a triangle must be greater than the length of the third side. If a triangle has side lengths of $7$ and $10$, which inequality represents the possible lengths, $x$, of the third side of the triangle?', '["$x < 17$", "$x > 17$", "$3 < x < 17$", "$x < 3$ or $x > 17$"]'::jsonb, 16, null),
  ('931878f7-60c7-548c-b80a-bc1b29861a5d', '413f6697-3442-5053-b12e-926fa81b6a8c', 'The graph of $y = f(x) + 4$ is shown. Which equation defines function $f$?', '["$f(x) = -6^{x} + 1$", "$f(x) = -6^{x} + 5$", "$f(x) = -6^{x} + 8$", "$f(x) = -6^{x} + 9$"]'::jsonb, 17, '![figure](/q/mar25/009.webp)'),
  ('0c645a3f-1d0c-5be3-878f-663c43e60000', '413f6697-3442-5053-b12e-926fa81b6a8c', 'In the figure, $LQ$ intersects $MP$ at point $R$, and $LM$ is parallel to $PQ$. The lengths of $MR$ and $RP$ are 8 and 14 units, respectively. The area of $\triangle LMR$ is 36 square units. What is the area of $\triangle PQR$, in square units?', '["$\\frac{576}{49}$", "$\\frac{144}{7}$", "63", "$\\frac{441}{4}$"]'::jsonb, 18, '![figure](/q/mar25/010.webp)'),
  ('ef40f6a1-0198-5754-b0b2-d6a1abc1b71e', '413f6697-3442-5053-b12e-926fa81b6a8c', 'The function $g$ is defined by $g(x) = 3x$. For what value of $x$ is $g(x) = 12$?', '[]'::jsonb, 19, null),
  ('e7e0302f-a195-5ad4-aafd-d81cb413a40f', '413f6697-3442-5053-b12e-926fa81b6a8c', 'Right rectangular prism $X$ is similar to right rectangular prism $Y$. The surface area of right
$2$
rectangular prism $X$ is $59$ square centimeters (cm), and the surface area of right rectangular prism Y is $1,475 \text{cm}^{2}$. The volume of right rectangular prism Y is $1,500 \text{cm}^{3}$. What is the sum of the volumes,
$3$
cm, of right rectangular prism $X$ and right rectangular prism $Y$?', '[]'::jsonb, 20, null),
  ('5380a766-e0e9-53e5-860d-4c4cb6e4aa9e', '413f6697-3442-5053-b12e-926fa81b6a8c', 'The function $f$ is defined by $f(x) = ab^{\frac{x}{n}}$, where $a$, $b$, and $n$ are constants, and $b$ and $n$ are integers, if $f(3) = 6$ and $f(5) = 150$, what is the value of $f(6)$?', '[]'::jsonb, 21, null),
  ('f1910ddd-48b9-5e4b-80fd-11128467262f', '413f6697-3442-5053-b12e-926fa81b6a8c', '$24x^{2} - (12a + 2b)x + ab = 0$
In the given equation, $a$ and $b$ are positive constants. The sum of the solutions to the given equation is $k(6a + b)$, where $k$ is a constant. What is the value of $k$?', '[]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
